import {GridActionsCellItem, GridColDef, GridRowId, GridRowParams} from "@mui/x-data-grid";
import {NavLink} from "react-router-dom";
import EditTwoToneIcon from "@mui/icons-material/EditTwoTone";
import DeleteTwoToneIcon from "@mui/icons-material/DeleteTwoTone";
import React from "react";
import {Translate} from "../../../i18n";

const statusColumns: (handleSetStatusToDelete: (id: GridRowId) => void, t: Translate) => GridColDef[] = (handleSetStatusToDelete, t) => [
    {
        field: "name",
        headerName: t("Название"),
        minWidth: 220,
        flex: 1,
    },
    {
        field: "isSystem",
        headerName: t("Тип"),
        width: 150,
        valueFormatter: (params) => params.value ? t("Системный") : t("Компании"),
    },
    {
        field: "Edit",
        headerName: t("Правка"),
        type: "actions",
        width: 92,
        getActions: (params: GridRowParams) => [
            <GridActionsCellItem
                icon={
                    <NavLink
                        style={{textDecoration: "none", color: "inherit"}}
                        to={`/statuses/editStatus/${params.id}`}
                    >
                        <EditTwoToneIcon/>
                    </NavLink>
                }
                label={t("Редактировать")}
                disabled={Boolean(params.row.isSystem)}
            />,
        ],
    },
    {
        field: "Delete",
        headerName: t("Удалить"),
        type: "actions",
        width: 92,
        getActions: (params: GridRowParams) => [
            <GridActionsCellItem
                icon={<DeleteTwoToneIcon/>}
                label={t("Удалить")}
                onClick={() => handleSetStatusToDelete(params.id)}
                disabled={Boolean(params.row.isSystem)}
            />,
        ],
    },
];

export default statusColumns;
