import {toast} from "react-toastify";
import {getApiErrorMessage} from "../../../api/errors";
import QueryError from "../../shared/QueryError";
import React, {useState} from "react";
import {Button, Dialog, DialogActions, DialogContent, DialogContentText, DialogTitle} from "@mui/material";
import {GridRowId} from "@mui/x-data-grid";
import {NavLink} from "react-router-dom";
import AddIcon from "@mui/icons-material/Add";
import CoreButton from "../../../ui/buttons/coreButton";
import {
    MainDiv,
    PageHeader,
    PageSubtitle,
    PageTitle,
    PageTitleGroup,
    StyledDataGrid,
    Surface,
} from "../../../ui/commonStyled/commonStyled";
import statusColumns from "./statusColumns";
import {useDeleteStatusMutation, useGetStatusesQuery} from "./statusesApi";
import Loader from "../../../ui/loader/loader";
import {useTranslation} from "../../../i18n";

const StatusesManagement = () => {
    const {data: statuses = [], isLoading, isError, error, refetch} = useGetStatusesQuery({});
    const [deleteStatus, {isLoading: isDeleting}] = useDeleteStatusMutation({});
    const {t} = useTranslation();

    const [statusToDeleteId, setStatusToDeleteId] = useState<GridRowId>();
    const [deleteWindowOpen, setDeleteWindowOpen] = useState(false);

    const handleSetStatusToDelete = (id: GridRowId) => {
        setDeleteWindowOpen(true);
        setStatusToDeleteId(id);
    };

    async function deleteStatusHandler() {
        if (isDeleting || statusToDeleteId === undefined) return;
        try {
            await deleteStatus(statusToDeleteId).unwrap();
            toast.success(t("Статус удалён."));
            setDeleteWindowOpen(false);
        } catch (failure) {
            toast.error(getApiErrorMessage(failure, t("Не удалось удалить запись.")));
        }
    }

    if (isLoading) {
        return <Loader/>;
    }

    if (isError) return <MainDiv><QueryError error={error} onRetry={refetch}/></MainDiv>;

    return (
        <MainDiv>
            <Dialog
                open={deleteWindowOpen}
                onClose={() => {if (!isDeleting) setDeleteWindowOpen(false);}}
            >
                <DialogTitle>{t("Подтверждение удаления статуса")}</DialogTitle>
                <DialogContent>
                    <DialogContentText>
                        {t("Вы действительно хотите удалить этот статус из системы?")}
                    </DialogContentText>
                </DialogContent>
                <DialogActions>
                    <Button disabled={isDeleting} onClick={() => setDeleteWindowOpen(false)}>{t("Отмена")}</Button>
                    <Button color="error" disabled={isDeleting} onClick={() => void deleteStatusHandler()} autoFocus>
                        {t("Удалить")}
                    </Button>
                </DialogActions>
            </Dialog>

            <PageHeader>
                <PageTitleGroup>
                    <PageTitle>{t("Статусы заказов")}</PageTitle>
                    <PageSubtitle>{t("Справочник этапов обработки заказов и клиентской коммуникации.")}</PageSubtitle>
                </PageTitleGroup>
                <NavLink to="createStatus" style={{textDecoration: "none"}}>
                    <CoreButton
                        muiType="success"
                        leftIcon={<AddIcon/>}
                        text={t("Создать статус")}
                    />
                </NavLink>
            </PageHeader>

            <Surface>
                <StyledDataGrid
                    pagination
                    autoHeight
                    rows={statuses}
                    columns={statusColumns(handleSetStatusToDelete, t)}
                    pageSizeOptions={[25, 50, 100]}
                    disableRowSelectionOnClick
                />
            </Surface>
        </MainDiv>
    );
};

export default StatusesManagement;
